import * as React from 'react';
import { it, expect } from 'vitest';
import { render, fireEvent, screen } from '@testing-library/react';
import { Field } from '@base-ui/react/field';

it('null controlled, consumer does not update', () => {
  render(<Field.Root data-testid="root"><Field.Control value={null as any} onValueChange={() => {}} /></Field.Root>);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
  console.log('NULL dirty', screen.getByTestId('root').hasAttribute('data-dirty'), 'filled', screen.getByTestId('root').hasAttribute('data-filled'));
});

it('controlled preventDefault on input, consumer sets', () => {
  let n = 0;
  function App() {
    const [v, setV] = React.useState('');
    return (
      <Field.Root validationMode="onChange" validate={() => { n++; return null; }}>
        <Field.Control value={v} onValueChange={setV} />
      </Field.Root>
    );
  }
  render(<App />);
  const c = screen.getByRole('textbox');
  c.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
  fireEvent.input(c, { cancelable: true, target: { value: 'a' } });
  console.log('PREVENT validate calls', n);
});

it('controlled cancel, consumer sets anyway', () => {
  let n = 0;
  function App() {
    const [v, setV] = React.useState('');
    return (
      <Field.Root data-testid="root" validationMode="onChange" validate={() => { n++; return null; }}>
        <Field.Control value={v} onValueChange={(x, d) => { d.cancel(); setV(x); }} />
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  console.log('CANCEL+set validate calls', n, screen.getByTestId('root').hasAttribute('data-dirty'));
});

it('uncontrolled cancel dirty/filled', () => {
  render(<Field.Root data-testid="root"><Field.Control onValueChange={(x, d) => d.cancel()} /></Field.Root>);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  console.log('UNCTRL cancel dirty', screen.getByTestId('root').hasAttribute('data-dirty'), 'filled', screen.getByTestId('root').hasAttribute('data-filled'), (screen.getByRole('textbox') as HTMLInputElement).value);
});

it('controlled: value then null', () => {
  function App() {
    const [v, setV] = React.useState<string | null>('x');
    return (<Field.Root data-testid="root"><Field.Control value={v as any} onValueChange={setV as any} /><button onClick={() => setV(null)}>n</button></Field.Root>);
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'y' } });
  fireEvent.click(screen.getByRole('button'));
  console.log('TONULL dirty', screen.getByTestId('root').hasAttribute('data-dirty'), 'filled', screen.getByTestId('root').hasAttribute('data-filled'));
});
EOF
